import json
BP={"refPath":"/Game/Gameplay/UI/V2/WBP_UIHUDExtras.WBP_UIHUDExtras"}
U="UMGToolSet.UMGToolSet."
O="editor_toolset.toolsets.object.ObjectTools."
A="editor_toolset.toolsets.asset.AssetTools."
def call(name,args):
    result=execute_tool(name,json.dumps(args));assert "returnValue" in result,(name,result)
    return result["returnValue"]
def ref(x):return x["refPath"] if isinstance(x,dict) else x
def update(obj,values):
    schema=json.loads(call(O+"list_properties",{"instance":obj}))
    norm=lambda x:x.lower().replace("_","")
    mapped={}
    for key,value in values.items():
        real=next((x for x in schema if norm(x)==norm(key)),None);assert real,(key,list(schema));mapped[real]=value
    call(O+"get_properties",{"instance":obj,"properties":list(mapped)})
    assert call(O+"set_properties",{"instance":obj,"values":json.dumps(mapped)})
def run():
    assert not call(A+"is_dirty",{"asset_path":"/Game/Gameplay/UI/V2/WBP_UIHUDExtras"})
    old=call(U+"GetWidgets",{"widgetBlueprint":BP});nodes={x["widgetName"]:x for x in old["widgets"]}
    assert "HUDExtrasRoot" in nodes
    created=False
    if "UnifiedReticle" not in nodes:
        node=call(U+"AddWidget",{"widgetBlueprint":BP,"widgetClass":{"refPath":"/Game/Gameplay/UI/V2/WBP_UIReticle.WBP_UIReticle_C"},"widgetDisplayName":"UnifiedReticle","parentWidget":nodes["HUDExtrasRoot"]["widget"],"childIndex":-1})
        assert node and node["widgetName"]=="UnifiedReticle";nodes["UnifiedReticle"]=node;created=True
    node=nodes["UnifiedReticle"]
    update(node["widget"],{"visibility":"HitTestInvisible"})
    update(node["slot"],{"layoutData":{"offsets":{"left":0,"top":0,"right":0,"bottom":0},"anchors":{"minimum":{"x":0,"y":0},"maximum":{"x":1,"y":1}},"alignment":{"x":0,"y":0}},"bAutoSize":False,"zOrder":100})
    assert call(U+"CompileWidgetBlueprint",{"widgetBlueprint":BP})
    assert call(A+"save_assets",{"asset_paths":["/Game/Gameplay/UI/V2/WBP_UIHUDExtras"]})
    final=call(U+"GetWidgets",{"widgetBlueprint":BP});new={x["widgetName"]:x for x in final["widgets"]}
    assert all(name in new and ref(new[name]["widget"])==ref(node["widget"]) for name,node in nodes.items())
    return {"created":created,"oldCount":len(old["widgets"]),"newCount":len(final["widgets"]),"originalObjectsPreserved":True,"overlayZ":100}
